const input = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(String(input.organization_id ?? '')) || !uuid.test(String(input.organization_document_id ?? ''))) throw new Error('Identificadores inválidos para WF-011');
const path = '/api/integrations/documents/' + String(input.organization_document_id) + '/file';
const downloadUrl = String(input.download_url ?? '');
const allowed = ['http://127.0.0.1:4001' + path, 'http://localhost:4001' + path, 'https://cernoia.secretbloom.tech' + path];
if (!allowed.includes(downloadUrl)) throw new Error('URL de descarga no autorizada');
return [{ json: { ...input, organization_id: String(input.organization_id), organization_document_id: String(input.organization_document_id), mime_type: String(input.mime_type ?? ''), download_url: 'http://127.0.0.1:4001' + path, n8n_execution_id: String($execution.id ?? '') } }];

